import "./mapCallouts.css";
import { getLocationName } from "./popupUtils";
import { getCurrentLang, translateWeaponType } from "./i18n";
import { themeColor } from "./theme";

// ─────────────────────────────────────────────────────────────────────────────
// Callouts : quelques cartes (lieu + headline) affichées en
// permanence par-dessus le globe, chacune reliée par un trait à son point.
//
//  - Les cartes sont des éléments DOM (pas des popups MapLibre) : on les
//    repositionne à chaque rendu de la carte (map.project) pour qu'elles
//    suivent le globe pendant la rotation.
//  - Un callout dont le point passe derrière le globe (ou sort de l'écran)
//    s'efface ; un autre point visible, important et éloigné des autres le
//    remplace (pendant le déplacement, puis à la fin).
//  - On ne force jamais : un callout n'est créé que si sa carte et son trait
//    ont la place (voir fill) ; sinon il n'apparaît pas, quitte à n'avoir
//    que quelques cartes, voire aucune, à l'écran.
// ─────────────────────────────────────────────────────────────────────────────

// Test : true → la carte affiche « lieu + type d'arme (traduit) » au lieu de « lieu + headline ».
// Repasser à false pour revenir à l'affichage avec la headline.
const CALLOUT_WEAPON_ONLY = false;

// true → la carte n'affiche QUE la headline (pas de nom de lieu). Prioritaire sur le mode test ci-dessus.
// Repasser à false pour revenir à « lieu + headline ».
const CALLOUT_HEADLINE_ONLY = true;

const SVG_NS = "http://www.w3.org/2000/svg";
const MOBILE_BREAKPOINT_PX = 768;
const FADE_MS = 260;
const OUT_COOLDOWN_MS = 1500; // blocage après sortie de zone (évite le va-et-vient)
const CLASH_GRACE_MS = 350; // un chevauchement doit durer avant de supprimer la carte
const REJECT_MS = 4000; // durée pendant laquelle un callout écarté ne peut pas être re-choisi
const ELBOW_PX = 16; // longueur du segment horizontal collé à la carte
const MAX_ANGLE_DEG = 75; // au-delà, le point est trop près du limbe du globe

// Zone centrale sans callout, en fraction du demi-écran (0 = désactivé, 0.5 = ellipse à mi-chemin du bord).
const CENTER_EXCLUSION = 0.5;
const CENTER_EXCLUSION_STICKY = 0.1; // tolérance en moins pour un callout déjà affiché (évite le clignotement)

// Admission d'un nouveau callout : on ne le crée QUE s'il a la place (carte + trait). On ne force
// jamais : mieux vaut peu de cartes (voire aucune) que des cartes qui apparaissent puis disparaissent.
const ADMIT_PAD = 12; // marge supplémentaire exigée à l'admission (vs maintien)
const MAX_SHIFT_PX = 24; // décalage max toléré de la carte (collée à un bord) par rapport à sa position idéale
const ADMIT_REJECT_MS = 2500; // un candidat sans place n'est pas retesté avant ce délai
const MAX_TESTS_PER_FILL = 30; // candidats testés au maximum à chaque remplissage

const isMobile = () =>
  typeof window !== "undefined" &&
  window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT_PX}px)`).matches;

const clamp = (v, min, max) => Math.max(min, Math.min(max, v));
const rad = Math.PI / 180;

const angularDistDeg = (lng1, lat1, lng2, lat2) => {
  const a =
    Math.sin(((lat2 - lat1) * rad) / 2) ** 2 +
    Math.cos(lat1 * rad) * Math.cos(lat2 * rad) * Math.sin(((lng2 - lng1) * rad) / 2) ** 2;
  return (2 * Math.asin(Math.min(1, Math.sqrt(a)))) / rad;
};

const importanceOf = (f) => {
  const n = Number(f.properties?.importance_score);
  return Number.isFinite(n) ? n : 1;
};
const timeOf = (f) => {
  const t = Date.parse(f.properties?.created_at ?? f.properties?.date);
  return Number.isFinite(t) ? t : 0;
};
const idOf = (f) =>
  f.properties?.id ?? `${f.geometry.coordinates.join(",")}|${f.properties?.created_at ?? ""}`;
// Même code couleur que les points de la carte : MIL → rouge, autres → bleu
const colorOf = (f) => (f.properties?.conflict_typology === "MIL" ? themeColor("danger") : themeColor("accent"));

// Le segment [a,b] traverse-t-il (ou est-il dans) le rectangle r ? (marge incluse)
const segmentHitsRect = (a, b, r, pad = 4) => {
  const L = r.left - pad, R = r.left + r.w + pad, T = r.top - pad, B = r.top + r.h + pad;
  const inside = (q) => q.x >= L && q.x <= R && q.y >= T && q.y <= B;
  if (inside(a) || inside(b)) return true;
  const cross = (p1, p2, p3, p4) => {
    const d = (p2.x - p1.x) * (p4.y - p3.y) - (p2.y - p1.y) * (p4.x - p3.x);
    if (d === 0) return false;
    const t = ((p3.x - p1.x) * (p4.y - p3.y) - (p3.y - p1.y) * (p4.x - p3.x)) / d;
    const u = ((p3.x - p1.x) * (p2.y - p1.y) - (p3.y - p1.y) * (p2.x - p1.x)) / d;
    return t >= 0 && t <= 1 && u >= 0 && u <= 1;
  };
  const tl = { x: L, y: T }, tr = { x: R, y: T }, br = { x: R, y: B }, bl = { x: L, y: B };
  return cross(a, b, tl, tr) || cross(a, b, tr, br) || cross(a, b, br, bl) || cross(a, b, bl, tl);
};
const polylineHitsRect = (pts, r, pad = 4) => {
  for (let i = 0; i < pts.length - 1; i++) if (segmentHitsRect(pts[i], pts[i + 1], r, pad)) return true;
  return false;
};

// Deux cartes se chevauchent-elles ? (gap = espace minimal exigé entre elles)
const rectsOverlap = (a, b, gap = 8) =>
  a.left < b.left + b.w + gap && a.left + a.w + gap > b.left && a.top < b.top + b.h + gap && a.top + a.h + gap > b.top;

// Deux callouts (chacun : rect de carte, poly du trait, p = point à l'écran) se gênent-ils ?
// `extra` élargit toutes les marges : on l'utilise à l'ADMISSION d'un nouveau callout (plus strict)
// que pour le MAINTIEN d'un callout déjà affiché (hystérésis, pas de va-et-vient).
const layoutClash = (a, b, extra = 0) =>
  rectsOverlap(a.rect, b.rect, 8 + extra) ||
  polylineHitsRect(a.poly, b.rect, 4 + extra) ||
  polylineHitsRect(b.poly, a.rect, 4 + extra) ||
  rectHidesPoint(a.rect, b.p, 10 + extra) ||
  rectHidesPoint(b.rect, a.p, 10 + extra);

// Le point q est-il caché par la carte r ? (marge = rayon de l'anneau + un peu d'air)
const rectHidesPoint = (r, q, pad = 10) =>
  q.x >= r.left - pad && q.x <= r.left + r.w + pad && q.y >= r.top - pad && q.y <= r.top + r.h + pad;

const escapeHTML = (v) =>
  String(v ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);

const parseProp = (v, fallback) => {
  if (v == null) return fallback;
  if (typeof v !== "string") return v;
  try {
    return JSON.parse(v);
  } catch {
    return fallback;
  }
};

// Même ordre de repli que la headline de popupUtils.js : traduite si dispo, sinon brute, sinon texte
const headlineOf = (props, lang) => {
  const ht = parseProp(props.headline_translations, {});
  const tr = parseProp(props.translations, {});
  return String(
    ht?.[lang] ||
      props[`headline_${lang}`] ||
      props.headline_translated ||
      props.headline ||
      tr?.[lang] ||
      props.text ||
      ""
  ).trim();
};

const weaponOf = (props, lang) =>
  props.weapon_type ? String(translateWeaponType(props.weapon_type, lang) || "").trim() : "";

// Deuxième ligne de la carte : type d'arme (mode test) ou headline
const subtitleOf = (props, lang) => (CALLOUT_WEAPON_ONLY ? weaponOf(props, lang) : headlineOf(props, lang));

const placeOf = (f, lang) => String(getLocationName(f.properties ?? {}, lang) || "").trim();

const cardHTML = (f, lang) => {
  const props = f.properties ?? {};
  const important = ["4", "5"].includes(String(props.importance_score || "0").trim());
  const cls = `map-callout-card${important ? " map-callout-card--important" : ""}${CALLOUT_HEADLINE_ONLY ? " map-callout-card--headline-only" : ""}`;
  if (CALLOUT_HEADLINE_ONLY) {
    return `
    <div class="${cls}">
      <span class="map-callout-headline">${escapeHTML(headlineOf(props, lang))}</span>
    </div>`;
  }
  return `
    <div class="${cls}">
      <span class="map-callout-place">${escapeHTML(placeOf(f, lang))}</span>
      ${subtitleOf(props, lang) ? `<span class="map-callout-headline">${escapeHTML(subtitleOf(props, lang))}</span>` : ""}
    </div>`;
};

// ── Rayon (px) du point dessiné sur la carte, pour que le trait s'arrête sur son bord ──
// À garder cohérent avec les couches de points de MapView.jsx (tweets-mil, tweets-other).
const lerpStops = (x, stops) => {
  if (x <= stops[0][0]) return stops[0][1];
  for (let i = 1; i < stops.length; i++) {
    if (x <= stops[i][0]) {
      const [x0, y0] = stops[i - 1];
      const [x1, y1] = stops[i];
      return y0 + ((y1 - y0) * (x - x0)) / (x1 - x0);
    }
  }
  return stops[stops.length - 1][1];
};
const LINE_GAP_PX = 0; // espace entre le bord du point et le début du trait (négatif : le trait mord sur le point)
// Anneau blanc des points à localisation explicite (couche tweets-explicit-ring de MapView.jsx) :
// décalage du cercle par rapport au point + demi-épaisseur du trait. À garder cohérent avec MapView.
const EXPLICIT_RING_GAP_PX = 1;
const EXPLICIT_RING_STROKE_PX = 1.2;
const isExplicitLocation = (f) => String(f.properties?.location_accuracy ?? "").trim().toLowerCase() === "explicit";
const defaultPointRadius = (f, zoom) => {
  // tweets-mil et tweets-other : même rayon, interpolé selon importance (1→5) puis selon le zoom (0→6),
  // + demi-contour
  const imp = importanceOf(f);
  const lo = lerpStops(imp, [[1, 2.5], [3, 3.5], [5, 6]]);
  const hi = lerpStops(imp, [[1, 3.5], [3, 5], [5, 8]]);
  const ring = isExplicitLocation(f) ? EXPLICIT_RING_GAP_PX + EXPLICIT_RING_STROKE_PX / 2 : 0;
  return lerpStops(zoom, [[0, lo], [6, hi]]) + 0.4 + ring;
};

const isValidPoint = (f) => {
  const c = f?.geometry?.type === "Point" && f.geometry.coordinates;
  return Array.isArray(c) && Number.isFinite(c[0]) && Number.isFinite(c[1]);
};

/**
 * @param {maplibregl.Map} map
 * @param {object}   opts
 * @param {(feature, event) => void} opts.onSelect  clic sur une carte (ouvre popup / dock)
 * @param {() => boolean} opts.isSuppressed         true → on masque tout (popup ouverte, mode dessin…)
 * @param {() => any}     opts.getExcludedId        id d'un tweet à ne pas proposer (tweet sélectionné)
 * @param {string} opts.hoverLayer                  couche de points dont le survol masque les callouts
 * @param {(feature, zoom: number) => number} opts.getPointRadius  rayon (px) du point dessiné : le trait
 *                                                  s'arrête sur son bord plutôt qu'en son centre
 * @param {number} opts.maxZoom                     au-delà, les callouts disparaissent
 * @param {{top,right,bottom,left}} opts.insets     marges réservées (barre de recherche, chronologie…)
 */
export function createMapCallouts(
  map,
  {
    onSelect,
    isSuppressed = () => false,
    getExcludedId = () => null,
    getPointRadius = defaultPointRadius,
    maxZoom = 5,
    hoverLayer = "tweets-hover-area", // couche dont le survol masque les callouts
    insets = { top: 72, right: 16, bottom: 96, left: 16 },
  } = {}
) {
  const container = map.getContainer();
  const layer = document.createElement("div");
  layer.className = "map-callouts";
  const svg = document.createElementNS(SVG_NS, "svg");
  svg.setAttribute("class", "map-callouts-lines");
  layer.appendChild(svg);
  container.appendChild(layer);

  let features = []; // candidats triés par score décroissant
  const active = new Map(); // id → entrée
  let hidden = false;
  let destroyed = false;
  let fillTimer = null;
  let lastLang = getCurrentLang();
  const rejected = new Map(); // id → fin de blocage : callouts écartés car une carte masquait un trait

  const maxCount = () => 2; // max 2 callouts simultanés (desktop et mobile)
  const minGap = () => (isMobile() ? 170 : 260); // distance mini (px) entre deux points choisis

  // ── Visibilité d'un point ────────────────────────────────────────────────
  const LngLatCtor = map.getCenter().constructor;
  const isOccluded = (lng, lat) => {
    const tr = map.transform;
    if (typeof tr?.isLocationOccluded !== "function") return false;
    try {
      return !!tr.isLocationOccluded(new LngLatCtor(lng, lat));
    } catch {
      return false;
    }
  };

  // Renvoie la position écran du point s'il est visible (face avant du globe, dans les marges)
  // sticky = true pour un callout déjà affiché : seuils plus larges (hystérésis) afin qu'un point
  // qui oscille autour du limbe ou d'une marge ne fasse pas clignoter la carte.
  const locate = (lng, lat, sticky = false) => {
    const maxAngle = MAX_ANGLE_DEG + (sticky ? 8 : 0);
    const m = sticky ? -24 : 0; // marge négative = zone élargie
    if (map.getProjection?.()?.type !== "mercator") {
      const c = map.getCenter();
      if (angularDistDeg(c.lng, c.lat, lng, lat) > maxAngle) return null;
      if (!sticky && isOccluded(lng, lat)) return null;
    }
    const p = map.project([lng, lat]);
    const w = container.clientWidth;
    const h = container.clientHeight;
    if (
      p.x < insets.left + m || p.x > w - insets.right - m ||
      p.y < insets.top + m || p.y > h - insets.bottom - m
    ) {
      return null;
    }
    // Zone centrale exclue : on ne garde que les points vers la périphérie de l'écran
    const nx = (p.x - w / 2) / (w / 2);
    const ny = (p.y - h / 2) / (h / 2);
    const minR = CENTER_EXCLUSION - (sticky ? CENTER_EXCLUSION_STICKY : 0);
    if (Math.hypot(nx, ny) < minR) return null;
    return p;
  };

  // ── Création / suppression d'un callout ─────────────────────────────────
  const measure = (e) => {
    e.w = e.el.offsetWidth;
    e.h = e.el.offsetHeight;
  };

  const render = (e) => {
    e.el.innerHTML = cardHTML(e.feature, getCurrentLang());
  };

  // Sonde cachée : mesure la taille d'une carte AVANT de la créer, pour savoir si elle a la place.
  const probe = document.createElement("div");
  probe.className = "map-callout is-off";
  probe.style.visibility = "hidden";
  probe.style.pointerEvents = "none";
  layer.appendChild(probe);
  const sizeCache = new Map();
  const sizeOf = (feature, lang) => {
    const key = `${idOf(feature)}|${lang}|${isMobile() ? "m" : "d"}`;
    let size = sizeCache.get(key);
    if (!size) {
      probe.innerHTML = cardHTML(feature, lang);
      size = { w: probe.offsetWidth, h: probe.offsetHeight };
      if (sizeCache.size > 400) sizeCache.clear();
      sizeCache.set(key, size);
    }
    return size;
  };

  // Gabarit d'un callout (sans toucher au DOM) : rectangle de la carte, trait coudé, et décalage
  // subi par la carte (collée à un bord de l'écran) par rapport à sa position idéale.
  // size = { w, h } ; dir : côté de la carte (-1 gauche / 1 droite) ; vdir : -1 au-dessus / 1 en dessous.
  const layoutFor = (feature, p, size, dir, vdir) => {
    const cw = container.clientWidth;
    const ch = container.clientHeight;
    const wantLeft = dir > 0 ? p.x + 36 : p.x - 36 - size.w;
    const wantTop = p.y + vdir * 24 - size.h / 2;
    const left = clamp(wantLeft, insets.left, Math.max(insets.left, cw - insets.right - size.w));
    const top = clamp(wantTop, insets.top, Math.max(insets.top, ch - insets.bottom - size.h));
    const rect = { left, top, w: size.w, h: size.h };

    // Trait coudé : diagonale depuis le point, puis court segment horizontal jusqu'au milieu du
    // bord de la carte tourné vers le point. Si le point est trop près de la carte (ou au-dessus /
    // en dessous), repli sur un trait droit vers le bord le plus proche.
    const midY = top + size.h / 2;
    const edgeX = dir > 0 ? left : left + size.w;
    const stubX = edgeX - dir * ELBOW_PX;
    const farEnough = dir > 0 ? p.x < stubX - 6 : p.x > stubX + 6;
    const poly = farEnough
      ? [p, { x: stubX, y: midY }, { x: edgeX, y: midY }]
      : [p, { x: clamp(p.x, left, left + size.w), y: clamp(p.y, top, top + size.h) }];
    // Le trait démarre sur le bord du point (rayon + petit espace), pas en son centre.
    // p reste le centre : il sert aux tests de recouvrement.
    const dx = poly[1].x - p.x;
    const dy = poly[1].y - p.y;
    const dist = Math.hypot(dx, dy);
    const r = getPointRadius(feature, map.getZoom()) + LINE_GAP_PX;
    if (dist > r + 2 && r > 0) poly[0] = { x: p.x + (dx / dist) * r, y: p.y + (dy / dist) * r };

    return { rect, poly, shift: Math.max(Math.abs(left - wantLeft), Math.abs(top - wantTop)) };
  };

  const applyLayout = (e) => {
    e.el.style.transform = `translate3d(${e.rect.left}px, ${e.rect.top}px, 0)`;
    e.line.setAttribute("points", e.poly.map((q) => `${q.x},${q.y}`).join(" "));
  };

  // Crée le callout (déjà validé par fill) : jamais appelé pour un candidat sans place.
  const add = (feature, p, size, layout, dir, vdir) => {
    const [lng, lat] = feature.geometry.coordinates;
    const el = document.createElement("div");
    el.className = "map-callout is-off";
    // Le clic ne doit ni déplacer la carte ni être capté par les handlers de la carte
    ["mousedown", "touchstart", "dblclick", "contextmenu"].forEach((t) =>
      el.addEventListener(t, (ev) => ev.stopPropagation())
    );
    el.addEventListener("click", (ev) => {
      ev.stopPropagation();
      onSelect?.(feature, ev);
    });

    const link = document.createElementNS(SVG_NS, "g");
    link.setAttribute("class", "map-callout-link is-off");
    link.style.setProperty("--c", colorOf(feature));
    const line = document.createElementNS(SVG_NS, "polyline");
    line.setAttribute("class", "map-callout-line");
    link.append(line);
    svg.appendChild(link);
    layer.appendChild(el);

    const entry = {
      id: idOf(feature), feature, el, link, line, lng, lat, p,
      w: size.w, h: size.h, dir, vdir, leaving: false,
      rect: layout.rect, poly: layout.poly,
    };
    render(entry);
    measure(entry); // mesure réelle (la sonde peut différer d'un pixel)
    applyLayout(entry); // bien placé dès le premier affichage (pas de saut depuis 0,0)
    active.set(entry.id, entry);
    requestAnimationFrame(() => {
      if (entry.leaving) return;
      el.classList.remove("is-off");
      link.classList.remove("is-off");
    });
    return entry;
  };

  const leave = (e) => {
    if (e.leaving) return;
    e.leaving = true;
    e.el.classList.add("is-off");
    e.link.classList.add("is-off");
    setTimeout(() => {
      e.el.remove();
      e.link.remove();
      active.delete(e.id);
    }, FADE_MS);
  };

  // ── Sélection des points à afficher ─────────────────────────────────────
  // Un candidat n'est admis que si SA carte et SON trait ont la place dès maintenant (pas de
  // chevauchement, rien de masqué, carte pas poussée loin de son point). Sinon il est écarté sans
  // jamais apparaître : on préfère moins de callouts à des callouts qui clignotent.
  const fill = () => {
    if (destroyed || hidden) return;
    const max = maxCount();
    const live = [...active.values()].filter((e) => !e.leaving);
    if (live.length >= max) return;

    const excluded = getExcludedId();
    const taken = live.map((e) => e.p);
    // Tout ce qui est encore visible à l'écran (y compris les cartes en fondu de sortie)
    const present = [...active.values()].filter((e) => e.rect);
    const gap = minGap();
    const now = Date.now();
    const lang = getCurrentLang();
    const cw = container.clientWidth;
    const ch = container.clientHeight;
    let tests = 0;

    if (rejected.size > 500) rejected.forEach((until, id) => until <= now && rejected.delete(id));

    for (const f of features) {
      if (live.length >= max || tests >= MAX_TESTS_PER_FILL) break;
      const id = idOf(f);
      if (active.has(id) || id === excluded) continue;
      if ((rejected.get(id) ?? 0) > now) continue;
      // Rien à afficher : pas de headline (mode headline seule) ou pas de nom de lieu
      if (CALLOUT_HEADLINE_ONLY ? !headlineOf(f.properties ?? {}, lang) : !placeOf(f, lang)) continue;
      const [lng, lat] = f.geometry.coordinates;
      const p = locate(lng, lat);
      if (!p) continue;
      if (taken.some((q) => Math.hypot(q.x - p.x, q.y - p.y) < gap)) continue;

      tests++;
      const size = sizeOf(f, lang);
      if (!size.w || !size.h) continue;
      const dir = p.x < cw / 2 ? -1 : 1;
      const vdir = p.y < ch / 2 ? -1 : 1;
      const layout = layoutFor(f, p, size, dir, vdir);
      const cand = { p, rect: layout.rect, poly: layout.poly };
      const fits =
        layout.shift <= MAX_SHIFT_PX &&
        !rectHidesPoint(layout.rect, p, 10 + ADMIT_PAD) &&
        !present.some((k) => layoutClash(cand, k, ADMIT_PAD));
      if (!fits) {
        rejected.set(id, now + ADMIT_REJECT_MS); // pas la place : on ne force pas
        continue;
      }
      const entry = add(f, p, size, layout, dir, vdir);
      live.push(entry);
      present.push(entry);
      taken.push(p);
    }
  };

  const scheduleFill = (delay) => {
    if (fillTimer && delay > 100) return; // throttle pendant le mouvement
    clearTimeout(fillTimer);
    fillTimer = setTimeout(() => {
      fillTimer = null;
      fill();
      frame();
    }, delay);
  };

  // ── Positionnement (à chaque rendu de la carte) ─────────────────────────
  function frame() {
    if (destroyed || hidden || !active.size) return;
    const w = container.clientWidth;
    const h = container.clientHeight;

    for (const e of active.values()) {
      const p = map.project([e.lng, e.lat]);
      e.p = p;
      if (!e.leaving && !locate(e.lng, e.lat, true)) {
        rejected.set(e.id, Date.now() + OUT_COOLDOWN_MS); // pas de retour immédiat
        leave(e);
      }

      // Côté de la carte : à l'opposé du centre de l'écran, avec hystérésis (pas de va-et-vient)
      if (e.dir == null) e.dir = p.x < w / 2 ? -1 : 1;
      else if (e.dir > 0 && p.x < w * 0.4) e.dir = -1;
      else if (e.dir < 0 && p.x > w * 0.6) e.dir = 1;
      // Idem en vertical : la carte ne saute pas de 48 px quand le point franchit le milieu
      if (e.vdir == null) e.vdir = p.y < h / 2 ? -1 : 1;
      else if (e.vdir > 0 && p.y < h * 0.45) e.vdir = -1;
      else if (e.vdir < 0 && p.y > h * 0.55) e.vdir = 1;

      // Plus de « poussée » des cartes les unes contre les autres : une carte reste à sa place
      // naturelle ; si elle gêne, elle est retirée ci-dessous (et non déplacée de force).
      const layout = layoutFor(e.feature, p, e, e.dir, e.vdir);
      e.rect = layout.rect;
      e.poly = layout.poly;
      applyLayout(e);
    }

    // Maintien : une carte ne doit jamais masquer un point ni un trait (le sien ou celui d'un autre),
    // ni en chevaucher une autre. Le problème doit durer CLASH_GRACE_MS pour qu'on la retire (elle
    // est alors bloquée quelques secondes). Les plus anciennes sont prioritaires.
    const kept = [];
    let dropped = false;
    const nowMs = Date.now();
    for (const e of active.values()) {
      if (e.leaving || !e.rect) continue;
      const clash = rectHidesPoint(e.rect, e.p) || kept.some((k) => layoutClash(e, k));
      if (clash) {
        e.clashSince ??= nowMs;
        if (nowMs - e.clashSince > CLASH_GRACE_MS) {
          rejected.set(e.id, nowMs + REJECT_MS);
          leave(e);
          dropped = true;
          continue;
        }
      } else {
        e.clashSince = null;
      }
      kept.push(e);
    }
    if (dropped) scheduleFill(150);
  }

  // ── Événements de la carte ───────────────────────────────────────────────
  const onRender = () => frame();
  const onMove = () => scheduleFill(450); // remplace les callouts disparus même pendant la rotation
  const onMoveEnd = () => scheduleFill(60);
  const onResize = () => {
    active.forEach(measure);
    frame();
  };
  map.on("render", onRender);
  map.on("move", onMove);
  map.on("moveend", onMoveEnd);
  map.on("resize", onResize);
  // Survol d'un point : la popup complète s'ouvre (isSuppressed le détecte) → on masque tous les
  // callouts tout de suite, et on les réaffiche après la fermeture de la popup (délai de fermeture
  // de MapView + marge).
  const onPointHover = () => syncState();
  const onPointLeave = () => setTimeout(syncState, 500);
  map.on("mousemove", hoverLayer, onPointHover);
  map.on("mouseleave", hoverLayer, onPointLeave);

  // Popup ouverte, mode dessin, zoom trop fort, changement de langue : aucun évènement carte
  // ne le signale → petit contrôle périodique (très léger).
  const syncState = () => {
    if (destroyed) return;
    const shouldHide = isSuppressed() || map.getZoom() > maxZoom;
    if (shouldHide !== hidden) {
      hidden = shouldHide;
      layer.classList.toggle("is-hidden", hidden);
      if (!hidden) {
        frame();
        scheduleFill(60);
      }
    }
    const lang = getCurrentLang();
    if (lang !== lastLang) {
      lastLang = lang;
      active.forEach((e) => {
        render(e);
        measure(e);
      });
      frame();
    }
  };
  const stateTimer = setInterval(syncState, 400);

  return {
    // À appeler à chaque changement du jeu de tweets filtré (FeatureCollection.features)
    setFeatures(list) {
      features = (list || [])
        .filter(isValidPoint)
        .sort((a, b) => importanceOf(b) - importanceOf(a) || timeOf(b) - timeOf(a));
      const ids = new Set(features.map(idOf));
      active.forEach((e) => {
        if (!ids.has(e.id)) leave(e);
      });
      scheduleFill(50);
    },
    refresh() {
      lastLang = null; // force le re-rendu au prochain contrôle
      syncState();
    },
    destroy() {
      if (destroyed) return;
      destroyed = true;
      clearInterval(stateTimer);
      clearTimeout(fillTimer);
      map.off("render", onRender);
      map.off("move", onMove);
      map.off("moveend", onMoveEnd);
      map.off("resize", onResize);
      map.off("mousemove", hoverLayer, onPointHover);
      map.off("mouseleave", hoverLayer, onPointLeave);
      layer.remove();
      active.clear();
    },
  };
}